    return list(map(int, sys.stdin.readline().strip().split()))

n, m, s = read_ints()
edges = [[] for _ in range(n + 1)]

for _ in range(m):
    u, v, w = read_ints()
    edges[u].append((v, w))
    edges[v].append((u, w))

def dijkstra(start):
    dist = [float('inf')] * (n + 1)
    dist[start] = 0
    pq = [(0, start)]
    while pq:
        d, u = heapq.heappop(pq)
        if d > dist[u]:
            continue
        for v, w in edges[u]:
            if dist[u] + w < dist[v]:
                dist[v] = dist[u] + w
                heapq.heappush(pq, (dist[v], v))
    return dist

# Get the shortest distances from Bash's city to all other cities
dist_from_s = dijkstra(s)

